package com.aldaypcs.dumbwaystodie;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup("dumbwaystodie")
public interface DumbWaysToDieConfig extends Config
{
	@Range(max = 100)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "volume",
		name = "Volume",
		description = "How loud the death sound plays. 0 mutes it."
	)
	default int volume()
	{
		return 70;
	}
}

package com.aldaypcs.dumbwaystodie;

import java.awt.BorderLayout;
import java.awt.Color;
import java.util.List;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.Filepath;

class DumbWaysToDiePanel extends PluginPanel
{
	private final JLabel statusLabel = new JLabel();

	DumbWaysToDiePanel(DumbWaysToDiePlugin plugin)
	{
		setBorder(new EmptyBorder(10, 10, 10, 10));
		setLayout(new BorderLayout());

		JPanel content = new JPanel(new DynamicGridLayout(0, 1, 0, 8));

		JLabel title = new JLabel("Dumb Ways to Die");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		content.add(title);

		content.add(wrappedLabel("Choose a WAV file to play when your character dies. "
			+ "The volume is in the plugin's settings.", ColorScheme.LIGHT_GRAY_COLOR));

		content.add(statusLabel);

		JButton chooseButton = new JButton("Choose WAV file...");
		chooseButton.addActionListener(e ->
		{
			List<Filepath> chosen = new Filepath.Chooser()
				.setIsOpen()
				.setAcceptsFiles()
				.setDialogTitle("Choose a death sound")
				.addExtensionFilter("WAV audio", "wav")
				.showDialog(this);
			if (!chosen.isEmpty())
			{
				plugin.importSound(chosen.get(0));
			}
		});
		content.add(chooseButton);

		JButton testButton = new JButton("Play test");
		testButton.addActionListener(e -> plugin.playSound());
		content.add(testButton);

		add(content, BorderLayout.NORTH);
	}

	void showStatus(String text)
	{
		setStatus(text, Color.WHITE);
	}

	void showError(String text)
	{
		setStatus(text, ColorScheme.PROGRESS_ERROR_COLOR);
	}

	private void setStatus(String text, Color color)
	{
		SwingUtilities.invokeLater(() ->
		{
			statusLabel.setText("<html>" + text + "</html>");
			statusLabel.setForeground(color);
		});
	}

	private static JLabel wrappedLabel(String text, Color color)
	{
		JLabel label = new JLabel("<html>" + text + "</html>");
		label.setForeground(color);
		return label;
	}
}

package com.aldaypcs.dumbwaystodie;

import com.google.inject.Provides;
import java.io.IOException;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.sound.sampled.LineUnavailableException;
import javax.sound.sampled.UnsupportedAudioFileException;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Dumb Ways to Die",
	description = "Plays a sound of your choice when your character dies",
	tags = {"death", "sound", "audio"},
	internalName = DumbWaysToDiePlugin.INTERNAL_NAME
)
public class DumbWaysToDiePlugin extends Plugin
{
	static final String INTERNAL_NAME = "dumb-ways-to-die";
	static final String SOUND_FILE_NAME = "death.wav";
	private static final String TEST_COMMAND = "deathsound";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private DumbWaysToDieConfig config;

	@Inject
	private AudioPlayer audioPlayer;

	@Inject
	private ScheduledExecutorService executor;

	private Filepath soundFile;
	private DumbWaysToDiePanel panel;
	private NavigationButton navigationButton;
	private boolean remindedAboutMissingFile;

	@Override
	protected void startUp() throws Exception
	{
		Filepath directory = getPluginDirectory();
		directory.createDirectories();
		soundFile = directory.joinSegment(SOUND_FILE_NAME);
		remindedAboutMissingFile = false;

		panel = new DumbWaysToDiePanel(this);
		navigationButton = NavigationButton.builder()
			.tooltip("Dumb Ways to Die")
			.icon(ImageUtil.loadImageResource(getClass(), "panel_icon.png"))
			.priority(10)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navigationButton);

		executor.execute(this::updateStatus);
	}

	@Override
	protected void shutDown() throws Exception
	{
		clientToolbar.removeNavigation(navigationButton);
		navigationButton = null;
		panel = null;
		soundFile = null;
	}

	@Subscribe
	public void onActorDeath(ActorDeath actorDeath)
	{
		if (actorDeath.getActor() == client.getLocalPlayer())
		{
			playSound();
		}
	}

	// Typing ::deathsound in the chatbox plays the sound without having to die
	@Subscribe
	public void onCommandExecuted(CommandExecuted commandExecuted)
	{
		if (TEST_COMMAND.equalsIgnoreCase(commandExecuted.getCommand()))
		{
			playSound();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		Filepath file = soundFile;
		if (gameStateChanged.getGameState() != GameState.LOGGED_IN || remindedAboutMissingFile || file == null)
		{
			return;
		}

		remindedAboutMissingFile = true;
		executor.execute(() ->
		{
			if (!file.exists())
			{
				sendMissingFileMessage();
			}
		});
	}

	void playSound()
	{
		Filepath file = soundFile;
		int volume = config.volume();
		if (file == null || volume <= 0)
		{
			return;
		}

		// Loading the clip reads from disk, so keep it off the client thread
		executor.execute(() ->
		{
			if (!file.exists())
			{
				sendMissingFileMessage();
				return;
			}

			try
			{
				audioPlayer.play(file, toGain(volume));
			}
			catch (IOException | UnsupportedAudioFileException | LineUnavailableException e)
			{
				log.warn("Couldn't play the death sound", e);
				sendChatMessage("Dumb Ways to Die couldn't play its sound: " + e.getMessage());
			}
		});
	}

	// Called from the panel after the user picks a file
	void importSound(Filepath chosen)
	{
		Filepath destination = soundFile;
		DumbWaysToDiePanel currentPanel = panel;
		if (destination == null || currentPanel == null)
		{
			return;
		}

		executor.execute(() ->
		{
			try
			{
				SoundFiles.copyIfPlayable(chosen, destination);
				updateStatus();
			}
			catch (SoundFiles.NotPlayableException e)
			{
				currentPanel.showError("That file can't be used: " + e.getMessage() + ". 16-bit PCM WAV is safest.");
			}
			catch (IOException e)
			{
				log.warn("Couldn't import the death sound", e);
				currentPanel.showError("Couldn't copy that file: " + e.getMessage());
			}
		});
	}

	// Reads the sound file, so only call this from the executor
	private void updateStatus()
	{
		Filepath file = soundFile;
		DumbWaysToDiePanel currentPanel = panel;
		if (file == null || currentPanel == null)
		{
			return;
		}

		if (!file.exists())
		{
			currentPanel.showStatus("No sound chosen yet.");
			return;
		}

		try
		{
			currentPanel.showStatus(String.format("Sound set (%.1f seconds).", SoundFiles.lengthSeconds(file)));
		}
		catch (IOException | SoundFiles.NotPlayableException e)
		{
			currentPanel.showError("The saved sound can't be played. Choose another WAV file.");
		}
	}

	// AudioPlayer takes gain in decibels; 100% volume is 0 dB
	private static float toGain(int volumePercent)
	{
		return (float) (20 * Math.log10(volumePercent / 100.0));
	}

	private void sendMissingFileMessage()
	{
		sendChatMessage("Dumb Ways to Die has no sound yet. Choose a WAV file in its sidebar panel.");
	}

	private void sendChatMessage(String message)
	{
		clientThread.invokeLater(() -> client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null));
	}

	@Provides
	DumbWaysToDieConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DumbWaysToDieConfig.class);
	}
}

package com.aldaypcs.dumbwaystodie;

import java.io.BufferedInputStream;
import java.io.DataInputStream;
import java.io.EOFException;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardCopyOption;
import net.runelite.client.util.Filepath;

/**
 * Checks WAV files by reading their RIFF header directly. Hub plugins have to play sound through
 * AudioPlayer rather than javax.sound, and AudioPlayer can't inspect a file without playing it.
 */
final class SoundFiles
{
	private static final int FORMAT_PCM = 1;
	private static final int FORMAT_EXTENSIBLE = 0xFFFE;

	static final class NotPlayableException extends Exception
	{
		NotPlayableException(String message)
		{
			super(message);
		}
	}

	private SoundFiles()
	{
	}

	/**
	 * Copies source over destination, but only if it's an uncompressed WAV. Anything else, like an
	 * MP3, throws NotPlayableException and leaves the current sound untouched.
	 */
	static void copyIfPlayable(Filepath source, Filepath destination) throws IOException, NotPlayableException
	{
		lengthSeconds(source);
		source.copyTo(destination, StandardCopyOption.REPLACE_EXISTING);
	}

	static double lengthSeconds(Filepath file) throws IOException, NotPlayableException
	{
		try (DataInputStream in = new DataInputStream(new BufferedInputStream(file.openInputStream())))
		{
			if (!"RIFF".equals(readId(in)))
			{
				throw new NotPlayableException("not a WAV file");
			}
			readIntLE(in);
			if (!"WAVE".equals(readId(in)))
			{
				throw new NotPlayableException("not a WAV file");
			}

			int format = -1;
			long byteRate = 0;
			while (true)
			{
				String chunkId = readId(in);
				long chunkSize = readIntLE(in) & 0xFFFFFFFFL;

				if ("fmt ".equals(chunkId))
				{
					format = readShortLE(in);
					in.skipBytes(6); // channels and sample rate
					byteRate = readIntLE(in) & 0xFFFFFFFFL;
					skipFully(in, chunkSize - 12 + (chunkSize & 1));
				}
				else if ("data".equals(chunkId))
				{
					if (format != FORMAT_PCM && format != FORMAT_EXTENSIBLE)
					{
						throw new NotPlayableException("only uncompressed (PCM) WAV files work");
					}
					if (byteRate == 0)
					{
						throw new NotPlayableException("the WAV header is damaged");
					}
					return chunkSize / (double) byteRate;
				}
				else
				{
					// Chunks are padded to an even length
					skipFully(in, chunkSize + (chunkSize & 1));
				}
			}
		}
		catch (EOFException e)
		{
			throw new NotPlayableException("the file ends before any audio");
		}
	}

	private static String readId(DataInputStream in) throws IOException
	{
		byte[] id = new byte[4];
		in.readFully(id);
		return new String(id, StandardCharsets.US_ASCII);
	}

	private static int readIntLE(DataInputStream in) throws IOException
	{
		return Integer.reverseBytes(in.readInt());
	}

	private static int readShortLE(DataInputStream in) throws IOException
	{
		return Short.reverseBytes(in.readShort()) & 0xFFFF;
	}

	private static void skipFully(DataInputStream in, long count) throws IOException
	{
		while (count > 0)
		{
			long skipped = in.skip(count);
			if (skipped <= 0)
			{
				// skip() can return 0 before EOF; read a byte to tell the two apart
				in.readByte();
				skipped = 1;
			}
			count -= skipped;
		}
	}
}

package com.aldaypcs.dumbwaystodie;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class DumbWaysToDiePluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(DumbWaysToDiePlugin.class);
		RuneLite.main(args);
	}
}

package com.aldaypcs.dumbwaystodie;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.fail;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Arrays;
import net.runelite.client.util.Filepath;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class SoundFilesTest
{
	private static final int PCM = 1;
	private static final int MP3 = 0x55;

	@Rule
	public TemporaryFolder folder = new TemporaryFolder();

	@Test
	public void copiesPlayableWav() throws Exception
	{
		File source = writeWav("clip.wav", PCM, 2.0, true);
		Filepath destination = rooted(folder.newFolder("plugin")).joinSegment("death.wav");

		SoundFiles.copyIfPlayable(rooted(source), destination);

		assertArrayEquals(Files.readAllBytes(source.toPath()), Files.readAllBytes(Filepath.Unchecked.getPath(destination)));
		assertEquals(2.0, SoundFiles.lengthSeconds(destination), 0.01);
	}

	@Test
	public void replacesExistingSound() throws Exception
	{
		Filepath destination = rooted(folder.newFolder("plugin")).joinSegment("death.wav");
		SoundFiles.copyIfPlayable(rooted(writeWav("first.wav", PCM, 1.0, false)), destination);

		SoundFiles.copyIfPlayable(rooted(writeWav("second.wav", PCM, 3.0, false)), destination);

		assertEquals(3.0, SoundFiles.lengthSeconds(destination), 0.01);
	}

	@Test
	public void rejectsMp3() throws Exception
	{
		File mp3 = folder.newFile("song.mp3");
		Files.write(mp3.toPath(), new byte[]{'I', 'D', '3', 4, 0, 0, 0, 0, 0, 0, 1, 2, 3, 4, 5, 6});

		assertRejected(mp3);
	}

	@Test
	public void rejectsCompressedWav() throws Exception
	{
		assertRejected(writeWav("compressed.wav", MP3, 1.0, false));
	}

	@Test
	public void rejectsWavWithNoAudio() throws Exception
	{
		File full = writeWav("full.wav", PCM, 1.0, false);
		File truncated = folder.newFile("truncated.wav");
		Files.write(truncated.toPath(), Arrays.copyOf(Files.readAllBytes(full.toPath()), 30));

		assertRejected(truncated);
	}

	private void assertRejected(File file) throws Exception
	{
		Filepath destination = rooted(folder.newFolder()).joinSegment("death.wav");
		try
		{
			SoundFiles.copyIfPlayable(rooted(file), destination);
			fail("Expected " + file.getName() + " to be rejected");
		}
		catch (SoundFiles.NotPlayableException expected)
		{
			assertFalse(destination.exists());
		}
	}

	private static Filepath rooted(File file)
	{
		return Filepath.Unchecked.getRooted(file.toPath());
	}

	// Silent 16-bit 44.1 kHz stereo WAV, optionally with a LIST chunk like ffmpeg writes
	private File writeWav(String name, int formatCode, double seconds, boolean withListChunk) throws IOException
	{
		int sampleRate = 44100;
		int blockAlign = 4;
		int dataSize = (int) (sampleRate * seconds) * blockAlign;
		byte[] list = "INFOISFT\5\0\0\0test\0\0".getBytes(StandardCharsets.US_ASCII);

		ByteArrayOutputStream out = new ByteArrayOutputStream();
		out.write(ascii("RIFF"));
		out.write(intLE(0));
		out.write(ascii("WAVE"));
		out.write(ascii("fmt "));
		out.write(intLE(16));
		out.write(shortLE(formatCode));
		out.write(shortLE(2));
		out.write(intLE(sampleRate));
		out.write(intLE(sampleRate * blockAlign));
		out.write(shortLE(blockAlign));
		out.write(shortLE(16));
		if (withListChunk)
		{
			out.write(ascii("LIST"));
			out.write(intLE(list.length));
			out.write(list);
		}
		out.write(ascii("data"));
		out.write(intLE(dataSize));
		out.write(new byte[dataSize]);

		File file = folder.newFile(name);
		Files.write(file.toPath(), out.toByteArray());
		return file;
	}

	private static byte[] ascii(String id)
	{
		return id.getBytes(StandardCharsets.US_ASCII);
	}

	private static byte[] intLE(int value)
	{
		return ByteBuffer.allocate(4).order(ByteOrder.LITTLE_ENDIAN).putInt(value).array();
	}

	private static byte[] shortLE(int value)
	{
		return ByteBuffer.allocate(2).order(ByteOrder.LITTLE_ENDIAN).putShort((short) value).array();
	}
}
